//go:build linux && (amd64 || arm64 || arm || mips || mipsle)

package sandbox

import "maps"

// Arch is seccomp_data.arch for a process of this architecture.
func Arch() uint32 { return auditArch }

// Table maps the kernel's name of every system call of this architecture to its number, as
// golang.org/x/sys/unix numbers it (zsysnum_linux_*.go, generated by mksysnum.go). It is a copy.
func Table() map[string]uint32 { return maps.Clone(sysnums) }
